update public.ingredients set name_zh_cn='甘油', functions=array['humectant','hydration'], ingredient_family='humectant', plain_language_zh='经典吸湿保湿剂，帮助角质层抓住水分。', plain_language_en='A classic humectant that helps the stratum corneum retain water.', evidence_level='established' where normalized_name in ('glycerin','甘油glycerin');
update public.ingredients set name_zh_cn='烟酰胺', common_names=array['Vitamin B3'], functions=array['barrier_support','brightening','oil_control'], ingredient_family='vitamin_derivative', plain_language_zh='支持屏障、控油，并可辅助改善肤色不均。', plain_language_en='Supports the barrier and oil control and may help uneven skin tone.', evidence_level='established' where normalized_name in ('niacinamide','烟酰胺niacinamide');
update public.ingredients set name_zh_cn='角鲨烷', functions=array['emollient','barrier_support'], ingredient_family='emollient', plain_language_zh='轻质润肤剂，帮助减少水分流失并改善柔软度。', plain_language_en='A lightweight emollient that helps reduce water loss and improve softness.', evidence_level='established' where normalized_name in ('squalane','角鲨烷squalane');
